CREATE FUNCTION public.guard_consult_vat_author() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE v jsonb; n text; BEGIN IF (NEW.step_data->'vat') IS DISTINCT FROM (CASE WHEN TG_OP='UPDATE' THEN OLD.step_data->'vat' ELSE NULL END) AND NEW.step_data->'vat' IS NOT NULL AND NEW.step_data->'vat'<>'null'::jsonb THEN IF NOT public.is_aal2() OR NOT public.has_permission('vat.exemption') THEN RAISE EXCEPTION 'Alleen een bevoegde arts kan het btw-besluit wijzigen.'; END IF; v:=NEW.step_data->'vat'; IF jsonb_typeof(v->'exempt') IS DISTINCT FROM 'boolean' OR jsonb_typeof(v->'answers') IS DISTINCT FROM 'object' OR v->'answers'='{}'::jsonb OR EXISTS(SELECT 1 FROM jsonb_each_text(v->'answers') WHERE trim(coalesce(value,''))='') THEN RAISE EXCEPTION 'Beantwoord eerst alle fiscale vragen.'; END IF; SELECT full_name INTO n FROM public.profiles WHERE id=auth.uid(); NEW.step_data:=jsonb_set(NEW.step_data,'{vat}',v||jsonb_build_object('by',coalesce(n,'arts'),'at',now(),'userId',auth.uid())); END IF; RETURN NEW; END $$; CREATE TRIGGER consult_vat_author BEFORE INSERT OR UPDATE OF step_data ON public.consult_notes FOR EACH ROW EXECUTE FUNCTION public.guard_consult_vat_author();
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.settle_appointment(uuid,jsonb,jsonb,boolean,text)'::regprocedure) INTO d; IF strpos(d,'FOR l IN SELECT')=0 THEN RAISE EXCEPTION 'Betaalvalidatie niet gevonden'; END IF; d:=replace(d,'IF jsonb_typeof(_lines)<>''array''','IF _lines IS NULL OR _without_invoice IS NULL OR jsonb_typeof(_lines)<>''array'''); d:=replace(d,'FOR l IN SELECT value FROM jsonb_array_elements(_lines) LOOP','FOR l IN SELECT value FROM jsonb_array_elements(_lines) LOOP IF jsonb_typeof(l->''qty'') IS DISTINCT FROM ''number'' OR jsonb_typeof(l->''priceCents'') IS DISTINCT FROM ''number'' OR jsonb_typeof(l->''discountCents'') IS DISTINCT FROM ''number'' OR jsonb_typeof(l->''treatmentId'') IS DISTINCT FROM ''string'' THEN RAISE EXCEPTION ''Ongeldige betaalregel.''; END IF;'); d:=replace(d,'IF jsonb_typeof(_payments)<>''array''','IF _payments IS NULL OR jsonb_typeof(_payments)<>''array'''); d:=replace(d,'FOR p IN SELECT value FROM jsonb_array_elements(_payments) LOOP','FOR p IN SELECT value FROM jsonb_array_elements(_payments) LOOP IF jsonb_typeof(p->''amountCents'') IS DISTINCT FROM ''number'' OR jsonb_typeof(p->''method'') IS DISTINCT FROM ''string'' THEN RAISE EXCEPTION ''Ongeldige betaling.''; END IF;'); EXECUTE d; END $$;